const langContext = require.context('./', true, /\.lang.js$/)
let lang = {}
langContext.keys().forEach(fileName => {
  let langName = fileName.split('.')[1].split('/')[1]
  lang[langName] = langContext(fileName).default
})

export default {
  en: lang
}
