const tagsView = {
  state: {
    visitedViews: [],
    cachedViews: [],
    taskDetailInfo: ''
  },

  getters: {
    visitedViews: state => {
      return state.visitedViews
    },
    cachedViews: state => { return state.cachedViews }
  },
  mutations: {
    ADD_VISITED_VIEW: (state, view) => {
      if (state.taskDetailInfo) {
        view.meta.groupName = state.taskDetailInfo.groupName
        view.meta.taskName = state.taskDetailInfo.taskName
        state.taskDetailInfo = ''
      }
      if (state.visitedViews.some(v => v.path === view.path) || !!view.meta.hiddenTag) return
      state.visitedViews.push(
        Object.assign({}, view, {
          title: view.meta.title || 'no-name',
          groupName: view.meta.groupName || '',
          taskName: view.meta.taskName || ''
        })
      )
    },
    ADD_CACHED_VIEW: (state, view) => {
      if (state.cachedViews.includes(view.name)) return
      if (!view.meta.noCache) {
        state.cachedViews.push(view.name)
      }
    },
    DEL_VISITED_VIEW: (state, view) => {
      for (let [index, v] of state.visitedViews.entries()) {
        if (v.path === view.fullPath) {
          state.visitedViews.splice(index, 1)
          break
        }
      }
    },
    taskDetailInfoCommit (state, item) {
      state.taskDetailInfo = JSON.parse(JSON.stringify(item))
    }
  },
  actions: {
    addView ({ dispatch }, view) {
      dispatch('addVisitedView', view)
      dispatch('addCachedView', view)
    },
    addVisitedView ({ commit }, view) {
      commit('ADD_VISITED_VIEW', view)
    },
    addCachedView ({ commit }, view) {
      commit('ADD_CACHED_VIEW', view)
    },
    delVisitedView ({ commit, state }, view) {
      return new Promise((resolve) => {
        commit('DEL_VISITED_VIEW', view)
        resolve(state.visitedViews)
      })
    },
    taskDetailInfoDispatch ({ commit }, item) {
      commit('taskDetailInfoCommit', item)
    }
  }
}

export default tagsView
