let router = [
  {
    path: '/setting',
    name: 'setting',
    title: '设置',
    component: '@/home/public/index',
    redirect: '/setting/index',
    children: [
      {
        path: '/setting/index',
        name: 'setting_index',
        component: '@/home/setting/index',
        meta: { title: 'external.settingCenter', icon: 'el-icon-setting', showClose: true }
      },
      {
        path: '/setting/version',
        name: 'setting_version',
        component: '@/home/setting/version',
        meta: { title: '历史版本', icon: 'iconfont icon-gengxinjilu', showClose: true }
      }
    ]
  }
]

export default router
