<template>
  <div>
    <div class="wml-pagination">
      <el-pagination
        v-bind="$attrs"
        background
        @size-change="handleSizeChange"
        @current-change="handleCurrentChange"
        :current-page.sync="current"
        :page-size="pageSize"
        :layout="lay"
        :total="total"
      ></el-pagination>
    </div>
  </div>
</template>
<style scoped>
.wml-pagination {
  width: 100%;
  text-align: center;
}
</style>
<script>
/* name:分页器组件
 * 用法：<wml-pagination :currentPage.sync="" :pageSize="" :layout=""></wml-pagination>
 * 参数：currentPage 当前页数 pageSize 一页多少条数据 total 总条数
 * pageSizes 切换成每页多少条数据(选填)(自定义时必须传入一个数组(值必须为数字))默认值:[20, 50, 80, 100]
 * layout 可传入数字(0、1、2)默认值2(0、只显示显示总数和分页 1、显示分页和输入跳转页数 2、完成功能显示总条数 调整每页多少条 输入跳转页数) 也可以自定义
 * 抛出方法有 handleSizeChange 切换每页多少条  handleCurrentChange 切换页数 都包含了一个value的回调
 */
export default {
  name: 'WmlPage',
  // props: ['currentPage', 'pageSize', 'layout', 'pageSizes', 'total'],
  props: {
    currentPage: {
      type: Number
    },
    pageSize: {
      type: Number
    },
    layout: {
      type: Number
    },
    pageSizes: {
      type: Array,
      default: () => {
        return [20, 50, 80, 100]
      }
    },
    total: {
      type: [Number, String]
    }
  },
  data () {
    return {
      current: 1,
      lay: '',
      layoutArr: [
        'total, prev, pager, next',
        'prev, pager, next, jumper',
        'total, sizes, prev, pager, next, jumper'
      ]
    }
  },
  computed: {

  },
  created () {
    if (!this.layout) {
      this.lay = this.layoutArr[2]
    } else {
      if (this.layout instanceof Array === false) {
        this.lay = this.layoutArr[Number(this.layout)]
      }
    }
    if (this.pageSizes instanceof Array === true) {
      this.sizes = this.pageSizes
    }
  },
  methods: {
    currentPageChange (value) {
      this.$emit('update:currentPage', value)
    },
    handleSizeChange (val) {
      this.$emit('handleSizeChange', val) // 切换每页多少条
    },
    handleCurrentChange (val) {
      this.$emit('handleCurrentChange', val) // 切换页数
    }
  },
  watch: {
    current: {
      handler (newValue) {
        this.currentPageChange(newValue)
      }
    },
    currentPage: {
      handler (newValue) {
        this.current = newValue
      }
    }
  }
}
</script>
