// 引入全局组件
import WmlComponents from '@/components'
// 引入echart
import echarts from 'echarts'
// 引入element
import Element from 'element-ui'
// 引入XLSL
import XLSX from 'xlsx'
// 引入api
import api from '@/utils/api'
// 引入websocket
import websocket from '@/utils/websocket'

// 引入样式以及字体文件
import '@/assets/css/init.scss'
import 'element-ui/lib/theme-chalk/index.css'
import 'font-awesome/css/font-awesome.min.css'
import '@/assets/icon/iconfont.css'
export default {
  install (Vue, options) {
    // 注册全局组件
    for (let item in WmlComponents) {
      Vue.component(item, WmlComponents[item])
    }
    // 未接收到c#注入的SharpObj对象就给该对象赋值为空对象
    if (!window.SharpObj) {
      window.SharpObj = {}
    }
    // 绑定echart
    Vue.prototype.$echarts = echarts
    // 绑定XLSL
    Vue.prototype.$xlsx = XLSX

    // 注册element
    Vue.use(Element, { size: 'medium' })
    // 注册api
    Vue.use(api)

    // 調用c#方法獲取返回的ip以及端口號，并初始化websocket
    window.SharpObj.getLocalip(res => {
      Vue.use(websocket, res)
    })
    // 注册拦截器
    Object.defineProperties(Vue.prototype, {
      // Vue中访问SharpObj对象的时候拦截到访问window对象的SharpObj(c#注入)
      SharpObj: {
        get () { return window.SharpObj }
      }
    })
  }
}
