import Vue from 'vue'
import VueRouter from 'vue-router'
import _import from './_import_'
import component from './router.component'
import store from '@/store/index'
Vue.use(VueRouter)

const router = new VueRouter()
let getRoute = null
const routes = [
  ...component,
  {
    path: '*',
    name: 'all',
    redirect: '/login'
  },
  {
    path: '/login',
    name: 'login',
    component: '@/home/login/index'
  }
]

/**
 * @author: vince.Liang
 * @function: 路由导航钩子
 * @data: 2019-3-27
 * @param {type}
 * @return:
 */
router.beforeEach((to, from, next) => {
  if (!getRoute) {
    getRoute = routes
    routerGo(to, next)
  } else {
    next()
  }
})

/**
 * @author: vince.Liang
 * @function: 根据路由定义中的meta.showNav的值，递归路由列表选择需要显示在左侧的菜单的路由并且写到vuex中
 * @data: 2019-3-27
 * @param {type}
 * @return:
 */
function filterShowNavRouter (routes) {
  return routes.filter(route => {
    route.hasOwnProperty('children') && route.children.length > 0 && (route.children = filterShowNavRouter(route.children))
    if (route.hasOwnProperty('meta')) {
      return !!(route.meta.hasOwnProperty('showNav') && route.meta.showNav)
    } else {
      return false
    }
  })
}

/**
 * @author: vince.Liang
 * @function: 在路由第一次跳转时，做对应的操作逻辑
 * @data: 2019-3-27
 * @param {type}
 * @return:
 */
function routerGo (to, next) {
  getRoute = filterAsyncRouter(getRoute)
  router.addRoutes(getRoute) // 动态添加路由
  store.dispatch('setRoutes', filterShowNavRouter(getRoute))
  next({ ...to, replace: true })
}

/**
 * @author: vince.Liang
 * @function: 递归路由列表，将所有的路由定义的组件引入
 * @data: 2019-3-27
 * @param {type}
 * @return:
 */
function filterAsyncRouter (asyncRouterMap) {
  return asyncRouterMap.filter(route => {
    route.component && (route.component = _import(route.component))
    route.hasOwnProperty('children') && route.children.length > 0 ? route.children = filterAsyncRouter(route.children) : route.children = []
    return true
  })
}

export default router
