<template>
  <el-dialog
    :title="title"
    :visible.sync="v"
    :width="width"
    ref="dialog__wrapper"
    v-drag="drag"
    :top="top"
    :before-close="handleClose"
    :modal="modal"
    :center="center"
    :lock-scroll="lockScroll"
    :custom-class="customClass"
    :close-on-click-modal="closeOnClickModal"
    :close-on-press-escape="closeOnPressEscape"
    :show-close="showClose"
    :destroy-on-close="destroyOnClose"
    :fullscreen="fullscreen"
    :modal-append-to-body="modalAppendToBody"
    :append-to-body="appendToBody"
    @open="handleOpen"
    @opened="handleOpened"
    @close="close"
    @closed="handleClosed"
  >
    <slot name="title" slot="title"></slot>
    <slot name="default" slot="default"></slot>
    <slot name="footer" slot="footer"></slot>
  </el-dialog>
</template>
<script>
export default {
  data () {
    return {
      v: false
    }
  },
  props: {
    /* 弹窗显示与隐藏 */
    visible: {
      type: Boolean,
      default: false
    },
    /* 弹窗标题 */
    title: {
      type: String,
      default: ''
    },
    /* 是否拖拽,启动拖拽时destroy-on-close必须为false */
    drag: {
      type: Boolean,
      default: false
    },
    /* 点击关闭按钮或者遮罩的回调 */
    beforeClose: {
      type: [Function, String],
      default: ''
    },
    /* 自定义宽度 */
    width: {
      type: String,
      default: '50%'
    },
    /* 是否为全屏Dialog */
    fullscreen: {
      type: Boolean,
      default: false
    },
    /* Dialog CSS 中的 margin-top 值 */
    top: {
      type: String,
      default: '15vh'
    },
    /* 是否需要遮罩层 */
    modal: {
      type: Boolean,
      default: true
    },
    /* 是否对头部和底部采用居中布局 */
    center: {
      type: Boolean,
      default: false
    },
    /* 是否在 Dialog 出现时将 body 滚动锁定 */
    lockScroll: {
      type: Boolean,
      default: true
    },
    /* Dialog 的自定义类名 */
    customClass: {
      type: String,
      default: ''
    },
    /* 是否可以通过点击 modal 关闭 Dialog */
    closeOnClickModal: {
      type: Boolean,
      default: true
    },
    /* 是否可以通过按下 ESC 关闭 Dialog */
    closeOnPressEscape: {
      type: Boolean,
      default: true
    },
    /* 是否显示关闭按钮 */
    showClose: {
      type: Boolean,
      default: true
    },
    /* 关闭时销毁 Dialog 中的元素 */
    destroyOnClose: {
      type: Boolean,
      default: false
    },
    /* 遮罩层是否插入至 body 元素上，若为 false，则遮罩层会插入至 Dialog 的父元素上 */
    modalAppendToBody: {
      type: Boolean,
      default: true
    },
    /* Dialog 自身是否插入至 body 元素上 */
    appendToBody: {
      type: Boolean,
      default: false
    }
  },
  methods: {
    handleClose (done) {
      (typeof this.beforeClose) === 'function' ? this.beforeClose(done) : done()
    },

    /* Dialog 打开的回调 */
    handleOpen () {
      this.$emit('open')
    },

    /* Dialog 打开动画结束时的回调 */
    handleOpened () {
      this.$emit('opened')
    },
    /* Dialog 关闭的回调 */
    close () {
      this.$emit('close')
    },
    /* Dialog 关闭动画结束时的回调 */
    handleClosed () {
      this.$emit('closed')
    }
  },
  watch: {
    visible (val) {
      if (this.v === val) {
        return
      }
      this.v = val
    },
    v (val) {
      this.$emit('update:visible', val)
    }
  },
  created () {
    this.v = this.visible
  },
  directives: {
    drag: {
      bind (el, binding) {
        if (!binding.value) {
          return
        }
        var dialogHeader = el.querySelector('.el-dialog__header')
        var dialogEl = el.querySelector('.el-dialog')
        dialogHeader.style.cursor = 'move'
        dialogEl.style.left = '0px'
        dialogEl.style.top = '0px'
        dialogEl.style.marginBottom = '0px'
        const sty = dialogEl.currentStyle || window.getComputedStyle(dialogEl, null)
        dialogHeader.onmousedown = (e) => {
          var disX = e.clientX - dialogHeader.offsetLeft
          var disY = e.clientY - dialogHeader.offsetTop
          //  可见局域宽
          var clientWidth = document.body.clientWidth
          // 可见区域高
          var clientHeight = document.documentElement.clientHeight
          // 对话框宽度
          var dialogElWidth = dialogEl.offsetWidth
          // 对话框高度
          var dialogHeight = dialogEl.offsetHeight
          // 对话框距离左边距离
          var minDialogElLeft = dialogEl.offsetLeft
          // 对话框距离右边距离
          var maxDialogElLeft = clientWidth - dialogEl.offsetLeft - dialogElWidth
          // 对话框距离上边距离
          var minDialogElTop = dialogEl.offsetTop
          // 对话框距离下边距离
          var maxDialogElTop = clientHeight - dialogEl.offsetTop - dialogHeight
          // 元素现在left
          let styL = Number(sty.left.replace(/\px/g, ''))
          let styT = Number(Number(sty.top.replace(/\px/g, '')))
          document.onmousemove = function (e) {
            let left = e.clientX - disX
            let top = e.clientY - disY
            if (-(left) > minDialogElLeft) {
              left = -(minDialogElLeft)
            } else if (left > maxDialogElLeft) {
              left = maxDialogElLeft
            }
            if (-(top) > minDialogElTop) {
              top = -(minDialogElTop)
            } else if (top > maxDialogElTop) {
              top = maxDialogElTop
            }
            dialogEl.style.left = (styL + left) + 'px'
            dialogEl.style.top = (styT + top) + 'px'
          }
          document.onmouseup = function () {
            document.onmousemove = null
            document.onmousedown = null
            document.onmouseup = null
          }
        }
      }
    }
  }
}
</script>

