<template>
  <div>
    <!-- <textarea :id="id"></textarea> -->
    <tinymce-editer
      v-bind="$attrs"
      :init="init"
      ref="tinymce"
      :id="id"
      v-model="content"
      @onClick="onClick"
    ></tinymce-editer>
  </div>
</template>
<script>
import tinymce from 'tinymce'
import tinymceEditer from '@tinymce/tinymce-vue'
import plugin from './wml'
// import WmlOss from '@/utils/WmlOss.js'
import 'tinymce/themes/silver'
import 'tinymce/plugins/advlist' // 这几条引入是因为我的导入不了，不知道为啥
import 'tinymce/plugins/link'
import 'tinymce/plugins/image'
import 'tinymce/plugins/code'
import 'tinymce/plugins/table'
import 'tinymce/plugins/textcolor'
import 'tinymce/plugins/paste'
import 'tinymce/plugins/colorpicker'
import 'tinymce/plugins/wordcount'
import 'tinymce/plugins/imagetools'
const wml = document.querySelectorAll.bind(document)

export default {
  name: 'Tinymce',
  components: { tinymceEditer },
  props: {
    value: {
      type: String,
      default: ''
    },
    config: {
      type: Object,
      default () {
        return {}
      }
    },
    id: {
      type: String,
      default: () => {
        let len = 32
        let chars = 'ABCDEFGHJKMNPQRSTWXYZabcdefhijkmnprstwxyz2345678'
        let str = ''
        for (let i = 0; i < len; i++) {
          str += chars.charAt(Math.floor(Math.random() * chars.length))
        }
        return str
      }
    },
    baseUrl: {
      type: String,
      default: ''
    },
    plugins: {
      type: [String, Array],
      default () {
        return ['advlist', 'link', 'code', 'table', 'paste', 'image', 'imagetools']
      }
    },
    toolbar: {
      type: [String, Array],
      default () {
        return [`undo redo |  formatselect | bold italic forecolor backcolor | alignleft aligncenter alignright alignjustify 
                | bullist numlist outdent indent | lists image media table | removeformat | code | imagetools`]
      }
    },
    customToolBar: {
      type: [Object],
      default () {
        return {}
      }
    },
    toggleOrigin: {
      type: Boolean,
      default: false
    }
  },
  data: function () {
    return {
      content: this.value,
      init: {},
      editor: null
    }
  },
  created () {
    let self = this
    let toolbar = Object.keys(plugin)
    toolbar = [...self.toolbar, toolbar.join(' ')].join(' ')
    let config =
    {
      paste_data_images: true,
      forced_root_block: 'div',
      draggable_modal: true,
      elementpath: true,
      language_url: './tinymce/langs/zh_CN.js', // 语言包的路径
      language: 'zh_CN', // 语言n
      skin_url: './tinymce/skins/ui/oxide', // skin路径
      content_css: `./tinymce/skins/content/default/content.css`,
      height: 500, // 编辑器高度
      branding: false, // 是否禁用“Powered by TinyMCE”
      menubar: false, // 顶部菜单栏显示
      plugins: this.plugins,
      toolbar: toolbar,
      zIndex: 1576,
      setup: editor => {
        self.editor = editor
        for (const key in plugin) {
          if (plugin.hasOwnProperty(key)) {
            const element = plugin[key]
            self.editor.ui.registry['addButton'](key, {
              text: element.text,
              icon: element.icon,
              onAction: function () {
                element.onAction.call(self, self.editor)
                self.$emit(key, self.editor)
              }
            })
          }
        }
        editor.on('init', function (e) {
          Array.prototype.forEach.call(wml('.tox-tinymce-aux'), function (el) {
            // el.style.zIndex = (new Date()).getTime()
          })
        })
      },
      images_upload_handler: (blobInfo, success, failure) => {
        let reader = new FileReader()
        reader.readAsDataURL(blobInfo.blob())
        reader.onload = function (e) {
          success(e.target.result)
        }
      },
      init_instance_callback: (editor) => {
        self.editor = editor
        editor.on('input change undo redo', () => {
          self.$emit('contentChange', editor.getContent())
        })
      }
    }
    this.init = Object.assign(config, this.config)
  },
  mounted () {
  },
  updated () {
    // this.editor.render()
  },
  methods: {
    onClick (e) {
      this.$emit('onClick', e, tinymce)
    },
    clear () {
      this.content = ''
    },
    setContent (v) {
      this.content = v
    }
  },
  beforeDestroy: function () {
    this.editor.destroy()
    // tinymce.remove(this.editor)
  },
  watch: {
    value (val) {
      this.content = val
    },
    content (newValue) {
      this.$emit('input', newValue)
    }
  }
}
</script>
<style  rel="stylesheet/scss" lang="scss" scoped>
