// 验证规则
const strategies = {
  // 非空
  isNonNull: function (value, errorMsg) {
    return value === '' ? errorMsg : false
  },
  // 最小长度
  minLength: function (value, length, errorMsg) {
    return value < length ? errorMsg : false
  },
  // 数值相等
  isNumberEq: function (value, condition, errorMsg) {
    return value !== Number(condition) ? errorMsg : false
  },
  // 数组中含有某元素
  isInclude: function (value, arrOption, errorMsg) {
    return JSON.parse(arrOption).indexOf(Number(value)) !== -1 ? errorMsg : false
  },
  // 数组中No某元素
  isNoInclude: function (value, arrOption, errorMsg) {
    return JSON.parse(arrOption).indexOf(Number(value)) === -1 ? errorMsg : false
  }
}

// 验证类
class WmlValidator {
  constructor () {
    this.rule = []
  }
  // 添加验证规则
  addRule (value, rules) {
    for (let ruleOption of rules) {
      let ruleArray = ruleOption.rule.split(':')
      let errorMsg = ruleOption.errorMsg
      this.rule.push(() => {
        let ruleName = ruleArray.shift()
        ruleArray.unshift(value)
        ruleArray.push(errorMsg)
        return strategies[ruleName](...ruleArray)
      })
    }
  }
  // 开始验证
  startValidate () {
    for (let validateFunc of this.rule) {
      let errorMsg = validateFunc()
      if (errorMsg) {
        this.rule = []
        return errorMsg
      }
    }
    this.rule = []
    return false
  }
  // 直接验证
  validate (value, rules) {
    if (Array.isArray(value) && rules === undefined) {
      for (let item of value) {
        this.addRule(item.value, item.rules)
      }
    } else {
      this.addRule(value, rules)
    }
    return this.startValidate()
  }
}

export default WmlValidator
