function WmlGetStorage (key) {
  if (!key) {
    Error('键(key) 不能为空')
  }
  return localStorage.getItem(key)
}

function WmlSetStorage (key, value) {
  localStorage.setItem(key, value)
}

export {
  WmlGetStorage,
  WmlSetStorage
}
