let socketFunction = {
  // 心跳重连
  Heartbeat: function () {
    this.heartCheck()
  },
  // 插入任务数据
  InsertTaskData: function (e) {
    this.emit('insertTaskData' + e.Data.TaskId, e)
  },
  // 插入日志
  InsertLog: function (e) {
    this.emit('insertLog' + e.Data.TaskId, e)
  },
  // 修改任务数据
  UpdateTaskData: function (e) {
    this.emit('updateTaskData' + e.Data.TaskId, e)
  },
  // 删除数据
  DeleteTaskData: function (e) {
    this.emit('deleteTaskData' + e.Data.TaskId, e)
  },
  // 修改任务状态
  UpdateTaskStatus: function (e) {
    this.emit('updateTaskStatus' + e.Data.TaskId, e)
  },
  // 修改图表
  UpdateChart: function (e) {
    this.emit('updateChart' + e.Data.TaskId, e)
  },
  // 营销数据
  MarketData: function (e) {
    this.emit('marketData' + e.Data.TaskId, e)
  },
  // 获取任务指标
  TaskIndicators: function (e) {
    this.emit('taskIndicators', e)
  },
  // 获取任务完成数
  TaskCompleted: function (e) {
    this.emit('taskCompleted' + e.Data.TaskId, e)
  },
  // 任务排序
  ContactSort: function (e) {
    this.emit('contactSort' + e.Data.TaskId, e)
  },
  // 实时排序
  ContactReorder: function (e) {
    this.emit('contactReorder' + e.Data.TaskId, e)
  },
  // 展示提示
  WmlMsg: function (e) {
    this.vm.$WmlMsg(e.Data.Msg, e.Data.Type)
  }
}

export default socketFunction
