let router = [{
  path: '/task',
  name: 'task',
  component: '@/home/public/index',
  redirect: '/task/index',
  children: [
    {
      path: 'index',
      name: 'task_index',
      component: '@/home/task/index',
      meta: { hiddenTag: true }
    },
    {
      path: 'export/:id',
      name: 'task_export',
      component: '@/home/task/export',
      meta: { title: '导出', icon: 'iconfont icon-daochushuju', showClose: true }
    }
  ]
}]

export default router
