import Vue from 'vue'
import App from '@/App'
import router from '@/router'
import store from '@/store'
import WmlCommon from '@/utils/WmlCommon'
import WmlResource from '@/utils/WmlResource'
import i18n from '@/lang'

Vue.config.productionTip = false

// 注册工具函数
Vue.use(WmlCommon)
// 注册全局资源
Vue.use(WmlResource)

window.app = new Vue({
  router,
  store,
  i18n,
  render: h => h(App)
}).$mount('#app')
