const apiContext = require.context('./apiList/', true, /\.api.js$/)
let api = {}
api.install = (Vue) => {
  let $api = {}
  apiContext.keys().forEach(apiName => {
    const Config = apiContext(apiName)
    const tmp = Config.default || Config
    for (let i in tmp) {
      $api[i] = (function () { return tmp[i] }())
    }
  })
  Vue.prototype.$api = $api
}

export default api
