import Vue from 'vue'
import axios from 'axios'
import config from '@/config.js'
import { Loading, Message } from 'element-ui'
import Router from '@/router'
import { WmlGetStorage, WmlSetStorage } from '@/utils/WmlCommon/WmlStorage'
// axios.defaults.withCredentials = true
/**
 * file:true 添加上传图片
 * loading:true 是否显示loading
 */
const service = axios.create({
  baseURL: config.host,
  timeout: config.timeout
  // headers: { 'Content-Type': 'multipart/form-data' }
})
service.withCredentials = true
service.interceptors.request.use(option => {
  console.log('--------------------------')
  // option.headers['Accept'] = 'application/json'
  // option.headers['uuid-token'] = getStorage('uuid-token')
  option.headers['access-token'] = WmlGetStorage('access-token')
  option.headers['plat-token'] = Vue.WmlGetStorage('plat-token')
  option.headers['client-version'] = 'v1.0.0'
  WmlSetStorage('client-version', 'v1.0.0')
  if (option.method === undefined) {
    option.method = 'get'
  }
  if (option.data === undefined) {
    option.data = {}
  }
  if (option.method === 'get') {
    option.params = option.data || {}
  }
  if (['PUT', 'POST', 'PATCH'].indexOf(option.method.toUpperCase()) !== -1) {
    option.data = option.data || {}
  }
  if (option.loading === true) {
    option.loadingService = openLoading()
  }

  if (option.file === true) {
    option.headers['Content-Type'] = 'multipart/form-data'
    option.data = formData(option.data)
  }
  return option
})

service.interceptors.response.use(
  response => {
    var accessToken = response.headers['access-token']
    var platToken = response.headers['plat-token']
    // var uuidToken = response.headers['uuid-token']
    if (accessToken) {
      WmlSetStorage('access-token', accessToken)
    }
    if (platToken) {
      WmlSetStorage('plat-token', platToken)
    }
    // if (uuidToken) {
    //   setStorage('uuid-token', uuidToken)
    // }
    if (response.config.loading) {
      closeLoading(response.config)
    }
    return response
  }, error => {
    // config, code, request, response
    console.log(error.response)
    if (Object.prototype.hasOwnProperty.call(error, 'response') && error.response !== undefined) {
      if (Object.prototype.hasOwnProperty.call(error.response, 'status') && error.response.status === 403) {
        Message({
          type: 'error',
          message: error.response.data.msg
        })
        Router.push({ path: '/' })
        return Promise.reject(error.response)
      }
    }
    closeLoading(error.config)
    Message({
      type: 'error',
      showClose: true,
      message: '网络错误, 请联系管理员'
    })
    return Promise.reject(error.response)
  })

service.prototype.all = function (promises) {
  return axios.all(promises)
}

function openLoading () {
  return Loading.service({ text: '请稍等...' })
}
function closeLoading (config = {}) {
  if (Object.prototype.hasOwnProperty.call(config, 'loadingService') && config.loadingService !== undefined) {
    config.loadingService.closeAll()
  }
}

function formData (data) {
  const formDataObj = new FormData()
  for (const item in data) {
    formDataObj.append(item, data[item])
  }
  return formDataObj
}

export default service
