<template>
  <div class="wml-mm-main" ref="wml-mm-main" v-if="show" :style="styleObj">
    <ul class="wml-mm-ul">
      <li
        class="wml-mm-li"
        v-for="(item, index) of menuList"
        :key="index"
        @click="selectMenuItem(item)"
      >
        <i :class="item.class"></i>
        <span>{{item.label}}</span>
      </li>
    </ul>
  </div>
</template>
<script>
export default {
  name: 'WmlMouseMenu',
  props: {
    visible: {
      type: Boolean,
      default: false
    },
    menuList: {
      type: Array,
      default: () => { return [] }
    },
    styleObj: {
      type: Object,
      default: () => { return {} }
    }
  },
  data () {
    return {
      show: true
    }
  },
  created () {
    this.show = this.visible
    window.addEventListener('click', this.close)
  },
  mounted () {
    if (this.$refs['wml-mm-main'].clientHeight + this.$refs['wml-mm-main'].offsetTop >= document.documentElement.clientHeight) {
      this.styleObj.top = document.documentElement.clientHeight - this.$refs['wml-mm-main'].clientHeight - 10 + 'px'
    }
  },
  methods: {
    close () {
      if (this.show) { this.show = !this.show }
    },
    selectMenuItem (item) {
      this.$emit('selectMenuItem', item.type)
    }
  },
  watch: {
    visible (val) {
      this.show = this.visible
    },
    show (val) {
      this.$emit('update:visible', val)
    },
    'styleObj.top' () {
      this.$nextTick(() => {
        if (this.$refs['wml-mm-main'].clientHeight + this.$refs['wml-mm-main'].offsetTop >= document.documentElement.clientHeight) {
          this.styleObj.top = document.documentElement.clientHeight - this.$refs['wml-mm-main'].clientHeight - 10 + 'px'
        }
      })
    }
  },
  destroyed () {
    window.removeEventListener('click', this.close)
  }
}
</script>
<style lang="scss">
.wml-mm-main {
  background: #fff;
  border: 1px solid #eaeefb;
  border-radius: 3px;
  overflow: hidden;
  box-shadow: 0 2px 12px 0 rgba(0, 0, 0, 0.1);
}

.wml-mm-li {
  width: 130px;
  display: flex;
  align-items: center;
  cursor: pointer;
  margin: 8px 0;
  padding: 8px 0;

  &:hover {
    background-color: #0daeff;
    color: #fff;
  }

  &:first-child {
    margin-top: 0;
  }

  &:last-child {
    margin-bottom: 0;
  }

  i {
    font-size: 16px;
    margin: 0 12px;
    color: #606266;
  }

  span {
    font-size: 14px;
    color: #606266;
  }

  &:hover i,
  &:hover span {
    color: #fff;
  }
}
</style>
