import Vue from 'vue'
let vm = new Vue()
export default {
  state: {
    marketingTest: {},
    taskIndicatorsTest: {
      TaskIndicators: 0,
      SurplusIndex: 0
    }

  },
  getters: {
    // getterTest: state => state.marketingTest,
    getterMarketingDataTest: state => taskId => {
      if (state.marketingTest[taskId]) {
        return state.marketingTest[taskId]
      }
      state.marketingTest[taskId] = {
        stopping: false,
        tableMax: false,
        echartTimer: null,
        ignoreEchart: 0,
        // 当前任务已经完成的条数
        completedNumber: 0,
        page: {
          total: 0,
          page: 1,
          num: 30
        },
        // 社交弹窗面板设置以及数据
        socialDialog: {
          show: false,
          data: [],
          title: '',
          panelData: []
        },
        // 表格加载提示
        tableLoading: false,
        tableLoadingText: '加载中',
        // 营销任务状态
        taskIsOpen: {
          // 邮箱任务状态
          IsOpenEmail: false,
          // LinkedIn任务状态
          IsOpenLinkedIn: false,
          // FaceBook任务状态
          IsOpenFaceBook: false,
          // Youtube任务状态
          IsOpenInstagram: false,
          // Twitter任务状态
          IsOpenTwitter: false,
          // 再营销状态
          IsReMarketing: false,
          TaskId: 0
        },
        // 营销步骤类名
        stepClass: [
          { class: 'step-start' },
          { class: 'step-green' },
          { class: 'step-blue' },
          { class: 'step-red' },
          { class: 'step-pink' },
          { class: 'step-brown' },
          { class: 'step-darkblue' },
          { class: 'step-purple' },
          { class: 'step-orange' }
        ],
        // 营销步骤
        marketingStep: [],
        resList: {},
        taskDataTable: [],
        crawlRunning: false,
        logData: [],
        dialogShow: false,
        settingData: {
          Email: {
            ConfigId: 2,
            ItemData: {
              EmailTypeList: [],
              Theme: '',
              Body: '',
              CompanySendLimit: 0
            },
            CanUse: false
          },
          LinkedIn: {
            ConfigId: 1,
            ItemData: {
              IsAddFriend: false,
              IsAddFirst: false,
              AddFriendLimitByCompany: 0,
              IdentityList: [],
              ValidationInformation: '',
              IsSendMsg: false,
              MsgContent: '',
              GetStaffPageLimit: 0
            },
            CanUse: false
          },
          Twitter: {
            ConfigId: 3,
            ItemData: {
              IsAddFriendList: false,
              IsTheFriendList: false,
              IsGenerateList: false,
              FriendListName: '',
              IsFilter: false,
              IsSendMsg: false,
              MsgContent: '',
              CompanyLimit: 100
            },
            CanUse: false
          },
          Facebook: {
            ConfigId: 'facebookConfig',
            ItemData: {
              CompanyLimit: 100,
              IsAddFriend: false,
              IsSendMessage: false,
              Message: '',
              AddFriendLimit: 100
            },
            CanUse: false
          },
          Instagram: {
            ConfigId: 'instagramConfig',
            ItemData: {
              IsFollow: false,
              Message: '',
              IsUnfollow: false,
              UnFollowThreshold: 0,
              MinUnfollowNumber: 0,
              MaxUnfollowNumber: 0,
              CompanyLimit: 100
            },
            CanUse: false
          },
          loading: true
        },
        // 爬虫echart图表设置
        spiderOption: {
          showAllSymbol: false,
          xAxis: {
            type: 'category',
            boundaryGap: false,
            data: [],
            axisLine: {
              lineStyle: {
                color: '#fff', // x轴的颜色
                width: 1// 轴线的宽度
              }
            },
            splitLine: { show: false }
          },
          yAxis: {
            type: 'value',
            axisLine: {
              lineStyle: {
                color: '#fff', // x轴的颜色
                width: 1// 轴线的宽度
              }
            },
            splitLine: {
              show: true,
              lineStyle: {
                color: ['#fff'],
                width: 1,
                type: 'solid'
              }
            }
          },
          series: [{
            symbol: 'none',
            data: [],
            type: 'line',
            smooth: true,
            itemStyle: {
              normal: {
                color: 'rgba(13,174,255, .2)'
              }
            },
            areaStyle: {
              normal: {
                color: new vm.$echarts.graphic.LinearGradient(0, 0, 0, 1, [{
                  offset: 0,
                  color: 'rgba(13,174,255, .8)'
                }, {
                  offset: 1,
                  color: 'rgba(255,255,255,1)'
                }]) // 改变区域颜色
              }
            }
          }],
          grid: {
            top: '20px',
            left: '30px',
            right: '10px',
            bottom: '30px',
            show: true,
            backgroundColor: '#C5E5FA',
            borderColor: '#fff',
            shadowColor: '#fff',
            borderWidth: '0'
          }
        }
      }
      // 第一次打开营销页面发送请求
      window.SharpObj.getTaskData(taskId, res => {
        res = JSON.parse(res)
        try {
          if (res.Code === 0) {
            // 获取到营销任务状态
            Object.assign(state.marketingTest[taskId].taskIsOpen, res.Data.Config)
            state.marketingTest[taskId].logData.push(...res.Data.LogTxt)
          } else {
            throw res.Msg
          }
        } catch (err) {
          console.log(err)
        }
      })
      return state.marketingTest[taskId]
    },

    getterTaskTableTest: state => taskId => {
      return state.marketingTest[taskId].taskDataTable
    },

    judgeTaskIdTest: state => taskId => {
      return !state.marketingTest[taskId]
    },

    getterSettingDataTest: state => taskId => {
      return state.marketingTest[taskId].settingData
    },
    getterMarketingStepTest: state => taskId => {
      return state.marketingTest[taskId].marketingStep
    },
    getterSpiderOptionTest: state => taskId => {
      return state.marketingTest[taskId].spiderOption
    },
    //  获取任务指标数据
    getterTaskIndicatorsTest: state => state.taskIndicatorsTest

  },
  mutations: {
    // 爬虫数据返回插入taskDataTable列表中
    commitCrawMarketingDataTest (state, res) {
      state.marketingTest[res.Data.TaskId].taskDataTable = res.Data.ContactInfoDataList
      // state.marketingTest[res.Data.TaskId].taskDataTable.push(...res.Data.ContactInfoDataList)
      state.marketingTest[res.Data.TaskId].page.total = state.marketingTest[res.Data.TaskId].page.total + res.Data.ContactInfoDataList.length
    },
    // 日志返回插入logData列表中
    commitPushLogDataTest (state, res) {
      state.marketingTest[res.Data.TaskId].logData.push(res.Data)
    },
    // 修改任务数据
    commitUpdateMarketingDataTest (state, res) {
      let { length } = state.marketingTest[res.Data.TaskId].taskDataTable
      for (let i = 0; i < length; i++) {
        if (state.marketingTest[res.Data.TaskId].taskDataTable[i].ContactId === res.Data.ContactInfoDataList[0].ContactId) {
          Object.assign(state.marketingTest[res.Data.TaskId].taskDataTable[i], res.Data.ContactInfoDataList[0])
        }
      }
    },
    // 营销数据返回处理
    commitMarketingStepTest (state, res) {
      res = res.Data
      res.TaskId = String(res.TaskId)
      let len = state.marketingTest[res.TaskId].marketingStep.length
      if (len === 0) {
        res.class = state.marketingTest[res.TaskId].stepClass[0].class
      } else {
        let classNow = state.marketingTest[res.TaskId].marketingStep[state.marketingTest[res.TaskId].marketingStep.length - 1].class
        for (let i = 0; i < state.marketingTest[res.TaskId].stepClass.length; i++) {
          if (state.marketingTest[res.TaskId].stepClass[i].class === classNow) {
            if (i === (state.marketingTest[res.TaskId].stepClass.length - 1)) {
              res.class = state.marketingTest[res.TaskId].stepClass[0].class
            } else {
              res.class = state.marketingTest[res.TaskId].stepClass[i + 1].class
            }
            //     break
          }
        }
      }
      state.marketingTest[res.TaskId].marketingStep.push(res)
    },
    // 删除数据返回处理
    commitDeleteMarketingDataTest (state, res) {
      let { length } = state.marketingTest[res.Data.TaskId].taskDataTable
      for (let i = 0; i < length; i++) {
        if (res.Data.ContactId === state.marketingTest[res.Data.TaskId].taskDataTable[i].ContactId) {
          state.marketingTest[res.Data.TaskId].taskDataTable.splice(i, 1)
          state.marketingTest[res.Data.TaskId].page.total--
          break
        }
      }
    },
    // 图表数据返回处理
    commitEchartTest (state, res) {
      if (!state.marketingTest[res.Data.TaskId].echartTimer) {
        state.marketingTest[res.Data.TaskId].echartTimer = setTimeout(() => {
          deceleration0(state.marketingTest[res.Data.TaskId], res)
          clearTimeout(state.marketingTest[res.Data.TaskId].echartTimer)
          state.marketingTest[res.Data.TaskId].echartTimer = null
        }, 3000)
      }
    },
    // 任务指标数据返回处理
    commitTaskIndicatorsTest (state, res) {
      Object.assign(state.taskIndicatorsTest, res)
    },
    // 任务完成数返回
    commitCompletedNumberTest (state, res) {
      state.marketingTest[res.Data.TaskId].completedNumber = res.Data.CompletedNumber
    },
    // 营销任务数据排序
    commitContactSortTest (state, res) {
      let resultObj = {}
      for (let key of res.Data.SortData) {
        resultObj[key] = []
      }
      for (let item of state.marketingTest[res.Data.TaskId].taskDataTable) {
        resultObj[item.Status].push(item)
      }
      let result = []
      for (let key of res.Data.SortData) {
        result.push(...resultObj[key])
      }
      state.marketingTest[res.Data.TaskId].taskDataTable.splice(0)
      state.marketingTest[res.Data.TaskId].taskDataTable.push(...result)
    },
    // 数据实时排序
    commitContactReorderTest (state, res) {
      state.marketingTest[res.Data.TaskId].taskDataTable.splice(0)
      state.marketingTest[res.Data.TaskId].taskDataTable.push(...res.Data.SortData)
    },
    commitDeleteTaskTest (state, taskId) {
      console.log(state.marketingTest[taskId])
    }
  },
  actions: {
    dispatchMarketingStepTest (context, res) {
      context.commit('commitMarketingStepTest', res)
    },
    dispatchEchartTest (context, res) {
      context.commit('commitEchartTest', res)
    },
    dispatchDeleteMarketingDataTest (context, res) {
      context.commit('commitDeleteMarketingDataTest', res)
    },
    dispatchCrawMarketingDataTest (context, res) {
      context.commit('commitCrawMarketingDataTest', res)
    },
    dispatchPushLogDataTest (context, res) {
      context.commit('commitPushLogDataTest', res)
    },
    dispatchUpdateMarketingDataTest (context, res) {
      context.commit('commitUpdateMarketingDataTest', res)
    },
    dispatchTaskIndicatorsTest (context, res) {
      context.commit('commitTaskIndicatorsTest', res)
    },
    dispatchCompletedNumberTest (context, res) {
      context.commit('commitCompletedNumberTest', res)
    },
    dispatchContactSortTest (context, res) {
      context.commit('commitContactSortTest', res)
    },
    dispatchContactReorderTest (context, res) {
      context.commit('commitContactReorderTest', res)
    },
    dispatchDeleteTaskTest (context, taskId) {
      context.commit('commitDeleteTaskTest', taskId)
    }

  }
}

// echart图表降速
function deceleration0 (marketingData, res) {
  if (marketingData.spiderOption.xAxis.data.length > 30) {
    deceleration3(marketingData, res)
    return
  }
  marketingData.spiderOption.xAxis.data.push(res.Data.Width)
  marketingData.spiderOption.series[0].data.push(res.Data.Height)
}

function deceleration3 (marketingData, res) {
  if (marketingData.spiderOption.xAxis.data.length > 60) {
    deceleration7(marketingData, res)
    return
  }
  if (marketingData.ignoreEchart % 3 === 0) {
    marketingData.spiderOption.xAxis.data.push(res.Data.Width)
    marketingData.spiderOption.series[0].data.push(res.Data.Height)
  }
  marketingData.ignoreEchart++
}

function deceleration7 (marketingData, res) {
  if (marketingData.spiderOption.xAxis.data.length > 90) {
    deceleration10(marketingData, res)
    return
  }
  if (marketingData.ignoreEchart % 7 === 0) {
    marketingData.spiderOption.xAxis.data.push(res.Data.Width)
    marketingData.spiderOption.series[0].data.push(res.Data.Height)
  }
  marketingData.ignoreEchart++
}

function deceleration10 (marketingData, res) {
  if (marketingData.ignoreEchart % 10 === 0) {
    marketingData.spiderOption.xAxis.data.push(res.Data.Width)
    marketingData.spiderOption.series[0].data.push(res.Data.Height)
  }
  marketingData.ignoreEchart++
}
