let router = [
  {
    path: '/marketing',
    name: 'marketing',
    title: 'external.taskCenter',
    component: '@/home/public/index',
    redirect: '/marketing/index',
    children: [
      {
        path: '/marketing/index/:id',
        name: 'marketing_index',
        component: '@/home/marketing/index',
        meta: { title: 'external.missionDetails', icon: 'el-icon-folder', showClose: true }
      }, {
        path: '/marketing/test/:id',
        name: 'marketing_test',
        component: '@/home/marketing/test',
        meta: { title: 'external.missionDetails', icon: 'el-icon-folder', showClose: true }
      },
      {
        path: '/marketing/reportchart',
        name: 'marketing_reportchart',
        component: '@/home/marketing/reportChart',
        meta: { title: 'external.marketingReport', icon: 'el-icon-s-marketing', showClose: true }
      }
    ]
  }
]

export default router
