// 确认框工具函数
import WmlConfirm from '@/utils/WmlCommon/WmlConfirm.js'
// 提示框工具函数
import WmlMsg from '@/utils/WmlCommon/WmlMsg.js'
// 验证器
import WmlValidator from '@/utils/WmlCommon/WmlValidator'
// 存储本地缓存公共函数
import { WmlGetStorage, WmlSetStorage } from '@/utils/WmlCommon/WmlStorage.js'

export default {
  install (Vue, options) {
    Vue.mixin({
      methods: {
        /**
         * @author: vince.Liang
         * @function: 频繁操作防抖动公共函数
         * @data: 2019-3-27
         * @param {function} func 具体处理回调
         * @param {Number} wait 间隔时间
         * @param {Boolean} order true为最后一次执行，false为第一次执行
         * @return: undefined
         */
        $debounce (func, wait, order = true) {
          let timer
          return function () {
            let _that = this
            let args = arguments
            if (order) {
              // 最后一次触发执行
              if (timer) clearTimeout(timer)
              timer = setTimeout(() => {
                func.call(_that, ...args)
              }, wait)
            } else {
              // 第一次触发执行
              if (timer) clearTimeout(timer)
              let callNow = !timer
              timer = setTimeout(() => {
                timer = null
              }, wait)
              callNow && func.call(_that, ...args)
            }
          }
        },

        /**
         * @author: vince.Liang
         * @function: 复制功能
         * @data: 2019-3-27
         * @param {String} text 要复制的字符窜
         * @return:undefined
         */
        $copy (text) {
          let input = document.createElement('input')
          input.value = String(text)
          input.style.opacity = 0
          document.body.appendChild(input)
          input.select()
          document.execCommand('Copy')
          this.$WmlMsg('复制成功，快去粘贴吧！')
          input.remove()
        },

        /**
         * @author: vince.Liang
         * @function: 路由跳转函数
         * @data: 2019-3-27
         * @param {Object} option 跳转的目标路由对象
         * @return: undefined
         */
        $to (option) {
          this.$router.push(option)
        },
        $lang (key) {
          return this.$t(key)
        }
      }
    })

    // 确认框工具函数
    Vue.prototype.$WmlConfirm = WmlConfirm
    // 提示框工具函数
    Vue.prototype.$WmlMsg = WmlMsg
    // 验证器
    Vue.prototype.$WmlValidator = new WmlValidator()
    // bus总线
    Vue.prototype.$bus = new Vue()
    // 获取本地缓存
    Vue.prototype.$WmlGetStorage = WmlGetStorage
    // 存入本地缓存
    Vue.prototype.$WmlSetStorage = WmlSetStorage
  }
}
