import socketFunction from '@/utils/websocket/socketFunctionMap'
import Vue from 'vue'
class WmlSocketClient {
  constructor (opts, vm) {
    if (this.instance) {
      return this.instance
    }
    let defaultConfig = Object.assign({
      protocol: location.protocol === 'http:' ? 'ws:' : 'wss:',
      port: location.port,
      url: opts.connection,
      ws: null,
      timeout: 5000,
      onmessageEvent: {},
      onopen: function () { },
      onmessage: function () { },
      onclose: function () { },
      onerror: function () { },
      onbeforesend: function () { },
      onbeforeclose: function () { }
    }, opts)
    // 已经重连次数
    this.reConnectNum = 1
    // 重连次数限定
    this.limitReConnectNum = 10
    // 重连计时器
    this.reConnectTimer = null
    // websocket配置
    this.config = defaultConfig
    // websocket实例
    this.ws = null
    // 是否开始心跳
    this.isHeartFlat = false
    // 重连状态，避免重复连接
    this.isReconnect = false
    // 重连间隔
    this.delay = 3000
    // 心跳检测发送心跳计时器
    this.timeoutObj = ''
    // 心跳检测发送间隔
    this.sendDelay = 300000
    // 心跳检测接收计时器
    this.timeoutServerObj = ''
    // 心跳检测接收超时时间
    this.serverDelay = 10000
    // vue原型
    // this.vm = vm
    this.init()
    WmlSocketClient.prototype.instance = this
  }
  /**
   * @author: vince.Liang
   * @function: 初始化websocket
   * @data: 2019-3-27
   * @param {type}
   * @return:
   */
  init () {
    let _self = this
    window.WebSocket = window.WebSocket || window.MozWebSocket
    if (!window.WebSocket) {
      console.error('浏览器不支持WebSocket')
    }
    let ws = new WebSocket(_self.config.url)
    _self.ws = ws
    ws.onopen = function (e) {
      _self.onopen(e)
    }
    ws.onmessage = function (e) {
      _self.onmessage(e)
    }
    ws.onclose = function (e) {
      console.log(e, '关闭连接')
      _self.onclose(e)
    }
    ws.onerror = function (e) {
      console.log(e, 'websocket连接错误')
      _self.onerror(e)
    }
  }
  send (str = '') {
    this.config.onbeforesend(this.config, this)
    this.ws.send(str)
  }
  close () {
    if (!this.ws) {
      console.error('链接已关闭')
      return
    }
    this.config.onbeforeclose(this.config, this)
    this.ws.close()
  }
  /**
    * @author: vince.Liang
    * @function: websocket重连操作
    * @data: 2019-3-27
    * @param {none}
    * @return: undefined
    */
  async reConnect () {
    if (this.reConnectNum > this.limitReConnectNum) {
      // if (await this.vm.$WmlConfirm('网络错误，连接已丢失，是否刷新页面')) {
      //   location.reload()
      //   this.vm.$WmlMsg('刷新成功')
      // }
      location.reload()
      return
    }
    if (this.isReconnect) return
    let _that = this
    _that.isReconnect = true
    clearTimeout(_that.reConnectTimer)
    _that.reConnectTimer = setTimeout(function () {
      _that.init()
      console.log('重连中')
      _that.isReconnect = false
      _that.reConnectNum++
    }, _that.delay)
  }
  /**
   * @author: vince.Liang
   * @function: 心跳检测
   * @data: 2019-3-27
   * @param {none}
   * @return: undefined
   */
  heartCheck () {
    let _that = this
    _that.timeoutObj && clearTimeout(_that.timeoutObj)
    _that.timeoutServerObj && clearTimeout(_that.timeoutServerObj)
    _that.timeoutObj = setTimeout(function () {
      _that.send('heart')
      _that.timeoutServerObj = setTimeout(function () {
        _that.close()
      }, _that.serverDelay)
    }, _that.sendDelay)
  }
  onclose (e) {
    this.isHeartFlat = false
    this.config.onclose(e)
    this.reConnect()
  }
  onmessage (e) {
    e = JSON.parse(e.data)
    socketFunction[e.Type].call(this, e)
    this.config.onmessage(e)
  }
  on (key, callback) {
    this.config.onmessageEvent[key] = callback
    window.addEventListener(key, this.config.onmessageEvent[key])
    // window.removeEventListener(key, this.config.onmessageEvent[key])
  }
  emit (key, e) {
    let eventOnMessage = new CustomEvent(key, { detail: e })
    window.dispatchEvent(eventOnMessage)
  }
  off (id) {
    for (let key in this.config.onmessageEvent) {
      if (key.indexOf(id) !== -1) {
        window.removeEventListener(key, this.config.onmessageEvent[key])
        Vue.delete(this.config.onmessageEvent, key)
      }
    }
  }
  onerror (e) {
    this.isHeartFlat = false
    this.config.onerror(e)
    this.reConnect()
  }
  onopen (e) {
    this.isHeartFlat = true
    this.config.onopen(e)
    this.heartCheck()
    this.reConnectNum = 1
  }
}
WmlSocketClient.prototype.instance = null

export default {
  install (Vue, connection, opts = {}) {
    var defaultConfig = Object.assign({
      protocol: location.protocol === 'http:' ? 'ws:' : 'wss:',
      port: location.port,
      url: connection,
      ws: null,
      timeout: 5000,
      onopen: function () { },
      onmessage: function () { },
      onclose: function () { },
      onerror: function () { },
      onbeforeclose: function () { }
    }, opts)
    if (!defaultConfig.url) { throw new Error('URL 必填') }
    let socket = new WmlSocketClient(defaultConfig)
    Object.defineProperties(Vue.prototype, {
      $socket: {
        get () {
          return socket
        }
      }
    })
  }
}
