const components = {
  // 登陆页
  '@/home/login/index': () => import('@/home/login/index'),
  // 首页
  '@/home/public/index': () => import('@/home/public/index'),
  // 上传文件
  '@/home/layout/index': () => import('@/home/layout/index'),
  // 任务详情
  '@/home/marketing/index': () => import('@/home/marketing/index'),
  // 任务详情测试
  '@/home/marketing/test': () => import('@/home/marketing/test'),
  // 任务导出
  '@/home/task/export': () => import('@/home/task/export'),
  // 营销报表
  '@/home/marketing/reportChart': () => import('@/home/marketing/reportChart'),
  // 设置
  '@/home/setting/index': () => import('@/home/setting/index'),
  // 历史版本
  '@/home/setting/version': () => import('@/home/setting/version'),
  //  套餐
  '@/home/setMeal/index': () => import('@/home/setMeal/index'),
  // 创建任务流程首页
  '@/home/task/index': () => import('@/home/task/index'),
  // 用户授权首页
  '@/home/empower/index': () => import('@/home/empower/index')
}

/**
 * @author: vince.Liang
 * @function: 导出提取路由对应组件的函数
 * @data: 2019-3-27
 * @param {type}
 * @return:
 */
export default function _import (view) {
  return components[view]
}
