const confirmType = {
  info: 'info',
  success: 'success',
  warning: 'warning',
  error: 'error'
}
async function WmlConfirm (message, title, cancelMessage, confirmButtonText, cancelButtonText, type, cancelType) {
  let confirm, arg
  arg = {
    title: title !== undefined ? title : this.$t('common.confirmDefaultTitle'),
    type: type !== undefined ? type : 'warning',
    cancelType: cancelType !== undefined ? cancelType : 'info',
    message: message !== undefined ? message : this.$t('common.confirmDefaultMessage'),
    cancelMessage: cancelMessage !== undefined ? cancelMessage : this.$t('common.confirmDefaultCancel'),
    cancelButtonText: cancelButtonText !== undefined ? cancelButtonText : this.$t('common.confitmDefaultBtnCancelText'),
    confirmButtonText: confirmButtonText !== undefined ? confirmButtonText : this.$t('common.confirmDefaultBtnConfirmText')
  }
  typeof message === 'object' && Object.assign(arg, message)
  try {
    confirm = await this.$confirm(arg.message, arg.title, {
      confirmButtonText: arg.confirmButtonText,
      cancelButtonText: arg.cancelButtonText,
      type: confirmType[arg.type]
    })
  } catch (error) {
    confirm = error
    this.$WmlMsg(arg.cancelMessage, confirmType[arg.cancelType])
  }
  if (confirm === 'confirm') {
    return true
  } else {
    return false
  }
}

export default WmlConfirm
