import ajax from '@/utils/api/request.js'
export default {
  // 任务组列表
  taskTaskGroupList (data, type, url) {
    if (!url) {
      url = '/ordinary/task-taskGroupList'
    }
    type = 'get'
    return ajax({
      url: url,
      method: type,
      data: data
    })
  }
}
