import Vue from 'vue'
import Vuex from 'vuex'

Vue.use(Vuex)

const storeContext = require.context('./modules/', true, /\.store.js$/)
let storeModule = {}
storeContext.keys().forEach(fileName => {
  let moduleName = fileName.split('.')[1].split('/')[1]
  if (storeModule.hasOwnProperty(moduleName)) {
    throw new Error(`vuex中模块文件重名，重名文件为${moduleName}`)
  }
  storeModule[moduleName] = storeContext(fileName).default || storeContext(fileName)
})
export default new Vuex.Store({
  modules: { ...storeModule }
})
