<template>
  <div :style="{height:'100%',width:'100%'}" ref="wml-editor">
    <!-- <div :id="id" type="text/plain" :style="{height:'100%',width:'100%'}"></div> -->
    <component
      :id="id"
      :ref="id"
      @input="contentChange"
      :style="{height:'100%',width:'100%'}"
      :is="useEditer"
      v-bind="$attrs"
      v-model="ComstValue"
      v-on="$listeners"
      :config = "config"
      :customToolBar="$props.customToolBar"
    ></component>
  </div>
</template>

<script>
import Tinymce from './components/tinymce'

export default {
  name: 'WmlEditor',
  components: {
    Tinymce,
    // Tinymce: () => import('./components/tinymce'),
    Ueditor: () => import('./components/ueditor')
  },
  props: {
    useEditer: {
      type: String,
      default: 'Tinymce'
    },
    id: {
      type: String,
      default: () => {
        let len = 32
        let chars = 'ABCDEFGHJKMNPQRSTWXYZabcdefhijkmnprstwxyz2345678'
        let str = ''
        for (let i = 0; i < len; i++) {
          str += chars.charAt(Math.floor(Math.random() * chars.length))
        }
        return str
      }
    },
    value: {
      type: String,
      default: ''
    },
    config: {
      type: Object,
      default: () => {
        return {
          labelMap: {
            wmlcustom: '外贸狼工具'
          }
        }
      }
    },
    height: {
      type: Number,
      default: 500
    }
  },
  data: () => {
    return {
      editor: null,
      content: null
    }
  },
  beforeUpdate () {
  },
  mounted () {
    // const self = this
    this.$nextTick(() => {
      this.editor = this.$refs[this.id]
    })
  },
  methods: {
    tempUediter () {

    },
    contentChange (v) {
      this.$emit('input', v)
    },
    getId () {
      return this.id
    },
    getContent () {
      return this.editor.getContent()
    },
    getEditor () {
      return this.editor
    },
    setContent (val) {
      this.editor.setContent(val)
    }
  },
  destoryed () {
    this.editor.destroy()
  },
  computed: {
    ComstValue: {
      get () {
        return this.value
      },
      set (v) {
        this.contentChange(v)
      }
    }
  },
  watch: {
    value (e) {
      if (e !== this.content) {
        // this.editor.setContent(e)
      }
    }
  }
}
</script>

