const routersContext = require.context('./routers/', true, /\.router.js$/)

let routes = []

routersContext.keys().forEach(fileName => {
  let config = routersContext(fileName)
  let tmp = config.default || config
  routes = [...routes, ...tmp]
})

export default routes
