export default {
  state: {
    routes: [],
    // 任务分组列表
    TaskList: [],
    // 版本号
    version: ''
  },
  getters: {
    TaskListGetter: function (state) {
      return state.TaskList
    },
    routes: function (state) {
      return state.routes
    },
    changeTaskStatus: state => (taskId, status) => {
      let { length } = state.TaskList
      for (let i = 0; i < length; i++) {
        let { length } = state.TaskList[i].Task
        for (let j = 0; j < length; j++) {
          if (state.TaskList[i].Task[j].Id === Number(taskId)) {
            state.TaskList[i].Task[j].Status = status
          }
        }
      }
    },
    getterTask: state => (taskId) => {
      let { length } = state.TaskList
      for (let i = 0; i < length; i++) {
        let { length } = state.TaskList[i].Task
        for (let j = 0; j < length; j++) {
          if (state.TaskList[i].Task[j].Id === Number(taskId)) {
            return state.TaskList[i].Task[j]
          }
        }
      }
    },
    getterVersion: state => state.version
  },
  mutations: {
    setRoutes (state, value) {
      state.routes = value
    },
    TaskListCommit (state, value) {
      state.TaskList = value
    },
    versionCommit (state, value) {
      state.version = value
    }
  },
  actions: {
    changeMenus ({ commit }, value) {
      commit('Menus', value)
    },
    // 设置vuex中的任务分组列表
    TaskListDispatch ({ commit }, value) {
      commit('TaskListCommit', value)
    },
    setRoutes ({ commit }, value) {
      commit('setRoutes', value)
    },
    versionDispatch ({ commit }, value) {
      commit('versionCommit', value)
    }
  }
}
