const msgType = {
  info: 'info',
  success: 'success',
  warning: 'warning',
  error: 'error'
}
const icon = {
  success: 'iconfont icon-chenggong',
  info: 'iconfont icon-warning',
  danger: 'iconfont icon-warning',
  warning: 'iconfont icon-Danger-'
}

const className = {
  success: 'wmlmsg-success',
  info: 'wmlmsg-info',
  danger: 'wmlmsg-danger',
  warning: 'wmlmsg-warning'
}

function WmlMsg (message, type = 'success', close = true) {
  let data = {}
  if (typeof message === 'object') {
    data = { ...message }
  } else {
    data = {
      message: message,
      showClose: close,
      type: msgType[type],
      duration: 1800,
      iconClass: icon[type],
      customClass: className[type]
    }
    this.$message.closeAll()
    return this.$message(data)
  }
}

export default WmlMsg
